from datetime import date, timedelta
from calendar import monthrange


def recur(start: str, rule: str, count: int) -> list[str]:
    first = date.fromisoformat(start)
    parts = rule.split()
    kind, step = parts[0], int(parts[1])
    weekdays = {name: i for i, name in enumerate(
        ("MO", "TU", "WE", "TH", "FR", "SA", "SU")
    )}

    if kind == "DAILY":
        return [
            (first + timedelta(days=i * step)).isoformat()
            for i in range(count)
        ]

    result = []
    period = 0

    if kind == "WEEKLY":
        monday = first - timedelta(days=first.weekday())
        selected = sorted(weekdays[wd] for wd in parts[2].split(","))
    elif kind == "YEARLY":
        target_month, target_day = map(int, parts[2].split("-"))

    while len(result) < count:
        candidates = []

        if kind == "WEEKLY":
            week_start = monday + timedelta(weeks=period * step)
            candidates = [
                week_start + timedelta(days=wd) for wd in selected
            ]

        elif kind == "MONTHLY":
            month_index = first.year * 12 + first.month - 1 + period * step
            year, month_zero = divmod(month_index, 12)
            month = month_zero + 1
            first_weekday, days_in_month = monthrange(year, month)

            if len(parts) == 3:
                requested = int(parts[2])
                day = days_in_month if requested == -1 else requested
            else:
                nth = int(parts[2])
                weekday = weekdays[parts[3]]
                if nth == -1:
                    last_weekday = (first_weekday + days_in_month - 1) % 7
                    day = days_in_month - (last_weekday - weekday) % 7
                else:
                    day = 1 + (weekday - first_weekday) % 7 + 7 * (nth - 1)

            if day <= days_in_month:
                candidates = [date(year, month, day)]

        else:  # YEARLY
            year = first.year + period * step
            if target_day <= monthrange(year, target_month)[1]:
                candidates = [date(year, target_month, target_day)]

        for candidate in candidates:
            if candidate >= first:
                result.append(candidate.isoformat())
                if len(result) == count:
                    return result

        period += 1

    return result
